377:     if (game.camOpen) {
378:       if (e.key === 'Escape') { game.closeCams(); return; }
379:       if (e.key === 'ArrowLeft') { e.preventDefault(); cycleCam(-1); return; }
380:       if (e.key === 'ArrowRight') { e.preventDefault(); cycleCam(1); return; }
381:       const n = parseInt(e.key, 10);
382:       if (n >= 1 && n <= 9) { e.preventDefault(); game.selectCam(CAM_ORDER[n - 1]); return; }
