726:     if (keys.has('arrowright') || keys.has('d')) kx += 1;
727:     if (keys.has('arrowup') || keys.has('w')) ky -= 1;
728:     if (keys.has('arrowdown') || keys.has('s')) ky += 1;
729:     if (kx || ky) {
730:       look.yaw = clamp(look.yaw - kx * dt * 1.35, -1.52, 1.52);
731:       look.pitch = clamp(look.pitch - ky * dt * .75, -.32, .3);
732:       world.targetYaw = look.yaw;
733:       world.targetPitch = look.pitch;
