739:     updateHud();
740:     syncWorldCharacters();
741:     for (const side of ['left', 'right']) {
742:       world.setDoor(side, game.doors[side]);
743:       world.setLight(side, game.lights[side]);
744:     }
745:     world.setPower(game.power / 100);
746:     if (game.camOpen) {
