755:     world.setPower(game.power / 100);
756:   }
757: 
758:   world.update(dt);
759: 
760:   // adaptive quality for sustained mobile framerates
761:   fpsAcc += dt; fpsFrames++;
762:   if (fpsAcc > 2.2) {
763:     const fps = fpsFrames / fpsAcc;
764:     if (fps < 46 && quality > .62) {
765:       quality = Math.max(.62, quality - .11);
766:       world.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75) * quality);
767:       goodWindows = 0;
