319:   _buildHall(side, key, floorM, wall, wains, trim, ceil) {
320:     const g = new THREE.Group();
321:     const len = 5.4;
322:     const width = 2.35;
323:     const hallX = side * (OFFICE.w + len / 2);
324:     const floor = plane(len, width, floorM, hallX, .001, OFFICE.doorZ, -Math.PI / 2);
325:     floor.receiveShadow = true;
326:     g.add(floor);
327:     g.add(plane(len, width, ceil, hallX, 2.62, OFFICE.doorZ, Math.PI / 2));
328:     // hallway side walls (parallel to x axis)
329:     for (const zs of [-1, 1]) {
330:       const wg = new THREE.Group();
331:       const lower = box(len, .85, .06, wains, 0, .425, 0);
332:       const upper = plane(len, 1.72, wall, 0, .85 + .86, .031);
333:       wg.add(lower, upper);
334:       wg.add(box(len, .06, .1, trim, 0, .86, .03));
335:       wg.position.set(hallX, 0, OFFICE.doorZ + zs * width / 2);
336:       if (zs < 0) wg.rotation.y = 0; else wg.rotation.y = Math.PI;
337:       g.add(wg);
338:     }
339:     // end wall
340:     const eg = new THREE.Group();
341:     eg.add(box(.08, 2.62, width, wall, 0, 1.31, 0));
342:     eg.position.set(side * (OFFICE.w + len), 0, OFFICE.doorZ);
343:     g.add(eg);
344:     // ceiling lamps
345:     const lampMat = new THREE.MeshBasicMaterial({ color: 0x312a1c });
346:     const lampGlows = [];
347:     for (const d of [1.3, 3.6]) {
348:       const lamp = box(.7, .04, .16, lampMat, side * (OFFICE.w + d), 2.56, OFFICE.doorZ);
349:       g.add(lamp);
350:       const glow = this._glow(0xffc98d, .95, .32);
351:       glow.position.set(side * (OFFICE.w + d), 2.5, OFFICE.doorZ);
352:       g.add(glow);
353:       lampGlows.push(glow);
354:     }
355:     this.doors[key].lampGlows = lampGlows;
356:     // shallow ceiling beams
357:     for (const d of [1.9, 2.9, 4.1]) {
358:       g.add(box(.08, .07, width, trim, side * (OFFICE.w + d), 2.585, OFFICE.doorZ));
359:     }
360:     // conduit running the length of the hall
361:     for (const zs of [-.92, .92]) {
362:       const pipe = new THREE.Mesh(new THREE.CylinderGeometry(.02, .02, len - .2, 6), new THREE.MeshStandardMaterial({ map: metalTexture(), roughness: .45, metalness: .7 }));
363:       pipe.rotation.z = Math.PI / 2;
364:       pipe.position.set(hallX, 2.5, OFFICE.doorZ + zs);
365:       g.add(pipe);
366:     }
367:     // fire alarm + staff door at the end
368:     const alarm = box(.13, .18, .07, mat({ color: 0xa8332a, roughness: .5 }), side * (OFFICE.w + 2.35), 1.95, OFFICE.doorZ + width / 2 - .08);
369:     g.add(alarm);
370:     const alarmGlow = this._glow(0xff4a32, .22, .5);
371:     alarmGlow.position.set(side * (OFFICE.w + 2.35), 1.98, OFFICE.doorZ + width / 2 - .12);
372:     g.add(alarmGlow);
373:     const endDoor = plane(1.02, 1.94, new THREE.MeshStandardMaterial({ map: metalTexture(), color: 0x8d8a80, roughness: .58, metalness: .42 }), side * (OFFICE.w + len - .05), .98, OFFICE.doorZ + .02, 0, side < 0 ? Math.PI / 2 : -Math.PI / 2);
374:     g.add(endDoor);
375:     g.add(box(1.16, .06, .05, trim, side * (OFFICE.w + len - .06), 1.99, OFFICE.doorZ + .02));
376:     g.add(box(1.12, .1, .05, trim, side * (OFFICE.w + len - .06), .05, OFFICE.doorZ + .02));
377:     const handle = new THREE.Mesh(new THREE.CylinderGeometry(.018, .018, .16, 6), new THREE.MeshStandardMaterial({ color: 0x9a9588, roughness: .3, metalness: .85 }));
378:     handle.rotation.z = Math.PI / 2;
379:     handle.position.set(side * (OFFICE.w + len - .13), 1.02, OFFICE.doorZ + .34);
380:     g.add(handle);
381:     const staffSign = plane(.42, .14, new THREE.MeshStandardMaterial({ map: signTexture(), roughness: .85 }), side * (OFFICE.w + len - .12), 1.65, OFFICE.doorZ + .34, 0, side < 0 ? Math.PI / 2 : -Math.PI / 2);
382:     g.add(staffSign);
383:     // hazard threshold at the office door
384:     const hazard = plane(.06, .7, new THREE.MeshStandardMaterial({ map: hazardTexture(), roughness: .8 }), side * (OFFICE.w + .28), .012, OFFICE.doorZ + width / 2 - .07, -Math.PI / 2);
385:     g.add(hazard);
386:     // low haze
387:     for (let i = 0; i < 3; i++) {
388:       const haze = this._glow(0xc9b18a, 1.5 + i * .6, .045);
389:       haze.position.set(side * (OFFICE.w + 1.2 + i * 1.6), .75 + i * .12, OFFICE.doorZ);
390:       g.add(haze);
391:     }
392:     // red EXIT sign just outside the office door
393:     const exitSign = plane(.34, .17, new THREE.MeshBasicMaterial({ map: exitTexture(), transparent: true }), side * (OFFICE.w + .06), 2.06, OFFICE.doorZ + 1.02);
394:     exitSign.rotation.y = side < 0 ? Math.PI / 2 : -Math.PI / 2;
395:     g.add(exitSign);
396:     const exitGlow = new THREE.PointLight(0xff2a18, 1.6, 3.4, 2);
397:     exitGlow.position.set(side * (OFFICE.w + .28), 2.0, OFFICE.doorZ + 1.02);
398:     g.add(exitGlow);
399:     // dim far-end practical light so the hall reads in the dark
400:     const farGlow = new THREE.PointLight(0x8d7a58, 1.1, 5.5, 2);
401:     farGlow.position.set(side * (OFFICE.w + len - .7), 2.35, OFFICE.doorZ);
402:     g.add(farGlow);
403: 
404:     // posters
405:     const posterSpots = [
406:       { kind: 'celebrate', d: 2.0, z: 0.55, s: .8 },
407:       { kind: 'safety', d: 3.6, z: -1.5, s: .7 },
408:       { kind: 'kids', d: 1.1, z: -1.7, s: .55 }
409:     ];
410:     for (const p of posterSpots) {
411:       const pm = new THREE.MeshStandardMaterial({ map: posterTexture(p.kind), roughness: .9 });
412:       const pl = plane(.62 * p.s / .62, .82 * p.s / .62, pm, side * (OFFICE.w + p.d), 1.5, OFFICE.doorZ + p.z * .7);
413:       pl.scale.set(p.s, p.s, 1);
414:       pl.rotation.y = side < 0 ? Math.PI / 2 : -Math.PI / 2;
415:       // Put against side wall instead
416:       pl.position.z = OFFICE.doorZ + (p.z > 0 ? width / 2 - .05 : -width / 2 + .05);
417:       pl.rotation.y = p.z > 0 ? Math.PI : 0;
418:       g.add(pl);
419:     }
420:     // floor scuffs and a "wet floor" cone
421:     const cone = new THREE.Mesh(
422:       new THREE.ConeGeometry(.18, .38, 14),
423:       mat({ color: 0xb99a32, roughness: .65 })
424:     );
425:     cone.position.set(side * (OFFICE.w + 1.6), .19, OFFICE.doorZ + .45);
426:     g.add(cone);
427:     this.scene.add(g);
428:     this.doors[key].hall = g;
429: 
430:     // door light source
431:     const light = new THREE.SpotLight(0xffb56a, 0, 9, Math.PI / 4.5, .55, 1.5);
432:     light.position.set(side * (OFFICE.w + .35), 2.45, OFFICE.doorZ);
433:     light.target.position.set(side * (OFFICE.w + 3.4), .3, OFFICE.doorZ);
434:     this.scene.add(light, light.target);
435:     light.castShadow = false;
436:     this.doors[key].light = light;
437:     this.doors[key].lightTarget = light.target;
438: 
439:     // fake volumetric cone
440:     const coneGeo = new THREE.ConeGeometry(1.5, 3.4, 18, 1, true);
441:     const coneMat = new THREE.MeshBasicMaterial({
442:       color: 0xffb060, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
443:       side: THREE.DoubleSide, depthWrite: false
444:     });
445:     const vol = new THREE.Mesh(coneGeo, coneMat);
446:     vol.position.set(side * (OFFICE.w + 1.9), 1.8, OFFICE.doorZ);
447:     vol.rotation.z = side * Math.PI / 2;
448:     vol.rotation.x = 0;
449:     // orient cone to point along hall (from ceiling to floor): rotate so tip up
450:     vol.rotation.set(0, 0, side < 0 ? Math.PI / 2 : -Math.PI / 2);
451:     vol.position.set(side * (OFFICE.w + 1.7), 1.55, OFFICE.doorZ);
452:     g.add(vol);
453:     this.doors[key].volume = vol;
454:     this.doors[key].volumeBase = coneMat;
455:   }
